/** The flag of India (Tiranga), drawn to the official 3:2 ratio with a 24-spoke Ashoka Chakra. */
export const IndiaFlag: React.FC<React.SVGProps<SVGSVGElement>> = (props) => (
    <svg viewBox="0 0 225 150" {...props}>
        <rect width="225" height="150" fill="#f93" />
        <rect width="225" height="50" y="50" fill="#fff" />
        <rect width="225" height="50" y="100" fill="#128807" />
        <g transform="translate(112.5,75)">
            <circle r="20" fill="#008" />
            <circle r="17.5" fill="#fff" />
            <circle r="3.5" fill="#008" />
            {/* One spoke is drawn once and mirrored by rotation, as in the official construction. */}
            <g id="india-flag-spokes-d">
                <g id="india-flag-spokes-c">
                    <g id="india-flag-spokes-b">
                        <g id="india-flag-spokes-a">
                            <circle r="0.875" fill="#008" transform="rotate(7.5) translate(17.5)" />
                            <path fill="#008" d="M 0,17.5 0.6,7 C 0.6,7 0,2 0,2 0,2 -0.6,7 -0.6,7 L 0,17.5 z" />
                        </g>
                        <use href="#india-flag-spokes-a" transform="rotate(15)" />
                    </g>
                    <use href="#india-flag-spokes-b" transform="rotate(30)" />
                </g>
                <use href="#india-flag-spokes-c" transform="rotate(60)" />
            </g>
            <use href="#india-flag-spokes-d" transform="rotate(120)" />
            <use href="#india-flag-spokes-d" transform="rotate(-120)" />
        </g>
    </svg>
);

