/**
 * Keeps the document's <head> metadata in step with the current route.
 *
 * Tags are updated in place by selector rather than rendered as React elements. React 19 hoists
 * `<meta>` natively, which bypasses react-helmet-async's reconciliation: Helmet appended its tags
 * instead of replacing the ones already in the HTML, leaving two `description` and two `og:title`
 * tags per page. Crawlers read the first match, so a pre-rendered page's own description was
 * being ignored in favour of the generic site-wide one from index.html.
 *
 * Upserting by selector guarantees exactly one tag per key, and means the values scripts/prerender.mjs
 * bakes into each file are updated rather than duplicated when the app takes over.
 */

/** Updates the tag if present, otherwise creates it. */
const upsertMeta = (attr: 'name' | 'property', key: string, content: string) => {
    let el = document.head.querySelector<HTMLMetaElement>(`meta[${attr}="${key}"]`);
    if (!el) {
        el = document.createElement('meta');
        el.setAttribute(attr, key);
        document.head.appendChild(el);
    }
    el.setAttribute('content', content);
};

export interface DocumentMeta {
    title: string;
    description: string;
    image?: string;
}

export const applyDocumentMeta = ({ title, description, image }: DocumentMeta) => {
    document.title = title;
    upsertMeta('name', 'description', description);
    upsertMeta('property', 'og:type', 'website');
    upsertMeta('property', 'og:title', title);
    upsertMeta('property', 'og:description', description);
    if (image) upsertMeta('property', 'og:image', image);
};
