import React from 'react';
import ReactDOM from 'react-dom/client';
import { RouterProvider, createRouter } from '@tanstack/react-router';
import { routeTree } from './routeTree.gen';
import { AuthContextProvider } from '@/contexts/AuthProvider';
import { UpdateKeyContext, useKeyContext } from '@/contexts/UpdateKeyContext';
import { IsTokenValid, GetUserRoles } from '@/utils/token';
import { PWAUpdatePrompt } from '@/components/PWAUpdatePrompt';
import { PWAInstallPrompt } from '@/components/PWAInstallPrompt';
import './globals.css';

const router = createRouter({
  routeTree,
  context: {
    auth: {
      isAuthenticated: false,
      roles: [],
    },
  },
});

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}

function InnerApp() {
  const { updateKey } = useKeyContext();
  const [authState, setAuthState] = React.useState({
    isAuthenticated: IsTokenValid(),
    roles: GetUserRoles() ?? [],
  });

  // Expose a way for Login/Logout to trigger auth re-evaluation
  React.useEffect(() => {
    const handler = () => {
      const newAuth = {
        isAuthenticated: IsTokenValid(),
        roles: GetUserRoles() ?? [],
      };
      setAuthState(newAuth);
      // Force router to re-evaluate beforeLoad with new context
      router.invalidate();
    };
    window.addEventListener('auth-changed', handler);
    return () => window.removeEventListener('auth-changed', handler);
  }, []);

  // Dismiss splash screen after app has rendered
  React.useEffect(() => {
    const splash = document.getElementById('splash');
    if (splash) {
      splash.classList.add('fade-out');
      setTimeout(() => splash.remove(), 500);
    }
  }, []);

  return (
    <AuthContextProvider>
      <UpdateKeyContext.Provider value={updateKey}>
        <RouterProvider router={router} context={{ auth: authState }} />
        <PWAUpdatePrompt />
        <PWAInstallPrompt />
      </UpdateKeyContext.Provider>
    </AuthContextProvider>
  );
}

// Mounting is idempotent: the root is cached on the container so a second execution of this
// module re-renders instead of creating a second root. Without this, anything that runs the
// entry twice — a stale service-worker shell referencing an older bundle URL alongside a fresh
// one, an HMR full reload, a duplicated script tag — mounts the whole app twice into #root and
// the user sees every page rendered twice.
const container = document.getElementById('root')! as HTMLElement & {
  __appRoot?: ReactDOM.Root;
};

container.__appRoot ??= ReactDOM.createRoot(container);

container.__appRoot.render(
  <React.StrictMode>
    <InnerApp />
  </React.StrictMode>
);
