import React from 'react';
import {
    Backdrop,
    Box,
    CircularProgress,
    LinearProgress,
    Paper,
    Typography,
} from '@mui/material';
import SystemUpdateAltIcon from '@mui/icons-material/SystemUpdateAlt';
import { useRegisterSW } from 'virtual:pwa-register/react';

/** Custom event used to manually trigger a PWA update + reload from anywhere
    (e.g. an "Update App" menu item). */
export const PWA_UPDATE_REQUEST_EVENT = 'alumni:pwa:update:request';

/** Imperatively check for a service-worker update and reload to apply it. */
export function requestPwaUpdate(): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new CustomEvent(PWA_UPDATE_REQUEST_EVENT));
}

/** Hard cap so the UI never gets stuck if an update stalls completely.
    Deliberately generous: installing a new worker re-downloads the whole app
    shell, which on a slow mobile connection routinely takes tens of seconds.
    Cutting it short and reloading anyway just re-serves the old build from the
    still-active worker, which is exactly what "the update did nothing" looks
    like to the user. */
const UPDATE_TIMEOUT_MS = 120_000;

/** Minimum time the "Updating app…" overlay stays up, so the restart never
    looks like an unexplained flash of the screen. */
const MIN_OVERLAY_MS = 1_200;

/** Newest registration, kept around so a manual update can act on it. */
let swRegistration: ServiceWorkerRegistration | null = null;

/** Throttle for background update checks triggered by app foregrounding. */
const FOREGROUND_CHECK_INTERVAL_MS = 15 * 60 * 1000;
let lastUpdateCheck = 0;

/** When the "Updating app…" overlay first became visible, so every restart path
    can honour MIN_OVERLAY_MS regardless of which one showed it. */
let overlayShownAt = 0;
let restartScheduled = false;

function reloadApp(): void {
    // `replace` restarts the app without adding a history entry.
    window.location.replace(window.location.href);
}

/** Reloads once the overlay has been on screen long enough to be readable. */
function scheduleRestart(): void {
    if (restartScheduled) return;
    restartScheduled = true;
    const shownFor = overlayShownAt ? Date.now() - overlayShownAt : MIN_OVERLAY_MS;
    window.setTimeout(reloadApp, Math.max(0, MIN_OVERLAY_MS - shownFor));
}

/**
 * Applies a pending service-worker update and restarts the app.
 *
 * The restart is gated on the new worker reaching `activated` (or taking
 * control). Reloading any earlier is pointless: the old worker still answers
 * from its own precache, so the user lands right back on the version they were
 * trying to leave.
 *
 * NOTE: `updateServiceWorker()` from `virtual:pwa-register` is a no-op when the
 * plugin runs in `registerType: 'autoUpdate'` mode, so the full flow (update
 * check -> skip waiting -> reload) has to be driven manually here.
 *
 * @param onGiveUp Called instead of restarting when there is nothing to
 *   activate after all — lets the caller take its overlay back down.
 */
async function applyUpdateAndRestart(onGiveUp: () => void): Promise<void> {
    if (typeof window === 'undefined') return;
    if (!('serviceWorker' in navigator)) {
        scheduleRestart();
        return;
    }

    let done = false;
    let timer = 0;
    const settle = (outcome: 'restart' | 'give-up') => {
        if (done) return;
        done = true;
        window.clearTimeout(timer);
        navigator.serviceWorker.removeEventListener('controllerchange', onControllerChange);
        if (outcome === 'restart') scheduleRestart();
        else onGiveUp();
    };
    const onControllerChange = () => settle('restart');

    // The new worker calls clients.claim() once activated, which fires
    // `controllerchange` — our signal that the new assets are live.
    navigator.serviceWorker.addEventListener('controllerchange', onControllerChange);
    timer = window.setTimeout(() => settle('give-up'), UPDATE_TIMEOUT_MS);

    // Workbox listens for this message and calls skipWaiting().
    const activate = (worker: ServiceWorker | null | undefined) =>
        worker?.postMessage({ type: 'SKIP_WAITING' });

    // Once a worker is activated it answers every later navigation even if it
    // never claimed this client, so that state is enough to reload safely.
    const restartWhenLive = (worker: ServiceWorker, registration: ServiceWorkerRegistration) => {
        worker.addEventListener('statechange', () => {
            if (worker.state === 'installed') activate(registration.waiting ?? worker);
            else if (worker.state === 'activated') settle('restart');
            else if (worker.state === 'redundant') settle('give-up');
        });
    };

    try {
        const registration =
            swRegistration ?? (await navigator.serviceWorker.getRegistration()) ?? null;
        if (!registration) {
            settle('restart');
            return;
        }
        swRegistration = registration;

        // Re-fetch sw.js so a version deployed after this session started is found.
        await registration.update().catch(() => { /* offline / network error */ });

        const waiting = registration.waiting;
        if (waiting) {
            restartWhenLive(waiting, registration);
            activate(waiting);
            return;
        }

        const installing = registration.installing;
        if (installing) {
            // Precaching the whole app shell can take a long time; wait it out.
            restartWhenLive(installing, registration);
            return;
        }

        // Already on the latest version — still honour the explicit user action,
        // but let an in-flight activation finish first so the reload is served
        // by the new worker.
        const active = registration.active;
        if (active && active.state === 'activating') {
            restartWhenLive(active, registration);
            return;
        }

        settle('restart');
    } catch {
        settle('restart');
    }
}

/**
 * Keeps the app on the latest service-worker version.
 *
 * Strategy:
 *  - On registration, check for updates immediately, hourly, and whenever the
 *    app returns to the foreground, so new deployments get picked up.
 *  - `registerType: 'autoUpdate'` activates a newly installed worker on its own.
 *    We intercept its reload via `onNeedReload` and show the "Updating app…"
 *    overlay first, so a background update never looks like a random refresh.
 *  - `PWA_UPDATE_REQUEST_EVENT` (the "Update App" menu item) forces the check,
 *    activates any pending worker immediately and restarts the app.
 */
export const PWAUpdatePrompt: React.FC = () => {
    const [updating, setUpdating] = React.useState(false);

    const showOverlay = React.useCallback(() => {
        if (!overlayShownAt) overlayShownAt = Date.now();
        setUpdating(true);
    }, []);

    const hideOverlay = React.useCallback(() => {
        if (restartScheduled) return;
        overlayShownAt = 0;
        setUpdating(false);
    }, []);

    /** Shows the overlay as soon as a *new* version starts downloading, so the
        user sees progress for the whole install, not just the final reload. */
    const watchForUpdate = React.useCallback(
        (registration: ServiceWorkerRegistration) => {
            registration.addEventListener('updatefound', () => {
                const installing = registration.installing;
                // No controller means this is the very first install, not an
                // update — nothing is being replaced, so stay out of the way.
                if (!installing || !navigator.serviceWorker.controller) return;
                showOverlay();
                // Only a stuck-guard. The overlay must not come down while the
                // install is still running: the app underneath is the old build,
                // and `onNeedReload` will restart into the new one the moment it
                // activates.
                const stuckGuard = window.setTimeout(hideOverlay, UPDATE_TIMEOUT_MS);
                installing.addEventListener('statechange', () => {
                    if (installing.state === 'redundant') {
                        window.clearTimeout(stuckGuard);
                        hideOverlay();
                    }
                });
            });
        },
        [showOverlay, hideOverlay],
    );

    useRegisterSW({
        // Fired by the plugin's autoUpdate flow once the new worker is active.
        // Taking it over lets us show the overlay instead of reloading blindly.
        onNeedReload() {
            showOverlay();
            scheduleRestart();
        },
        onRegisteredSW(_swUrl, registration) {
            if (!registration) return;
            swRegistration = registration;
            watchForUpdate(registration);
            // Check immediately on registration so an update queued from a
            // previous tab is picked up at app start.
            lastUpdateCheck = Date.now();
            registration.update().catch(() => { /* ignore */ });
            // Re-check hourly for long-lived sessions.
            setInterval(() => {
                lastUpdateCheck = Date.now();
                registration.update().catch(() => { /* ignore */ });
            }, 60 * 60 * 1000);
        },
    });

    React.useEffect(() => {
        const onVisibilityChange = () => {
            if (document.visibilityState !== 'visible') return;
            const now = Date.now();
            if (now - lastUpdateCheck < FOREGROUND_CHECK_INTERVAL_MS) return;
            lastUpdateCheck = now;
            swRegistration?.update().catch(() => { /* ignore */ });
        };
        document.addEventListener('visibilitychange', onVisibilityChange);
        return () => document.removeEventListener('visibilitychange', onVisibilityChange);
    }, []);

    React.useEffect(() => {
        const onManualUpdate = () => {
            showOverlay();
            void applyUpdateAndRestart(hideOverlay);
        };
        window.addEventListener(PWA_UPDATE_REQUEST_EVENT, onManualUpdate);
        return () => window.removeEventListener(PWA_UPDATE_REQUEST_EVENT, onManualUpdate);
    }, [showOverlay, hideOverlay]);

    return (
        <Backdrop
            open={updating}
            aria-live="assertive"
            aria-busy={updating}
            sx={{
                zIndex: (theme) => theme.zIndex.tooltip + 10,
                color: 'common.white',
                // Near-opaque so the stale UI underneath can't be mistaken for
                // an interactive app while the restart is in flight.
                bgcolor: 'rgba(12, 22, 40, 0.92)',
                backdropFilter: 'blur(4px)',
                px: 3,
            }}
        >
            <Paper
                elevation={24}
                sx={{
                    px: { xs: 4, sm: 6 },
                    py: { xs: 5, sm: 6 },
                    width: '100%',
                    maxWidth: 420,
                    borderRadius: 4,
                    textAlign: 'center',
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: 3,
                }}
            >
                <Box sx={{ position: 'relative', display: 'inline-flex' }}>
                    <CircularProgress size={88} thickness={4} />
                    <Box
                        sx={{
                            position: 'absolute',
                            inset: 0,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                        }}
                    >
                        <SystemUpdateAltIcon color="primary" sx={{ fontSize: 40 }} />
                    </Box>
                </Box>
                <Box>
                    <Typography variant="h5" component="p" gutterBottom sx={{ fontWeight: 700 }}>
                        Updating app…
                    </Typography>
                    <Typography variant="body1" sx={{ color: 'text.secondary' }}>
                        Installing the latest version. The app will restart automatically — please
                        don&apos;t close this window.
                    </Typography>
                </Box>
                <LinearProgress sx={{ width: '100%', height: 6, borderRadius: 3 }} />
            </Paper>
        </Backdrop>
    );
};
