import { Divider, IconButton, Menu, MenuItem, ListItemIcon, ListItemText } from "@mui/material";
import React, { useContext, useState } from "react";
import PersonIcon from "@mui/icons-material/Person";
import RefreshIcon from "@mui/icons-material/Refresh";
import LogoutIcon from "@mui/icons-material/Logout";
import LockOpenIcon from "@mui/icons-material/LockOpen";
import GetAppIcon from "@mui/icons-material/GetApp";
import SystemUpdateAltIcon from "@mui/icons-material/SystemUpdateAlt";
import { useNavigate } from '@tanstack/react-router';
import { AuthContext } from "@/contexts/AuthContext";
import { AuthServices } from "@/api";
import { ConfirmDialog } from "@/components/ui/ConfirmDialog";
import { SetAccessTokenData } from "@/utils/token";
import { AuthTokenResult } from "@/types/auth.types";
import { requestPwaInstall } from "@/components/PWAInstallPrompt";
import { requestPwaUpdate } from "@/components/PWAUpdatePrompt";

const isStandalone = (): boolean => {
  if (typeof window === 'undefined') return false;
  const navAny = window.navigator as Navigator & { standalone?: boolean };
  return (
    window.matchMedia?.('(display-mode: standalone)').matches ||
    window.matchMedia?.('(display-mode: window-controls-overlay)').matches ||
    window.matchMedia?.('(display-mode: minimal-ui)').matches ||
    window.matchMedia?.('(display-mode: fullscreen)').matches ||
    navAny.standalone === true ||
    document.referrer?.startsWith('android-app://')
  );
};

export const LoginLogoutButton: React.FunctionComponent = () => {
  const { isAuthenticated, setAuthData } = useContext(AuthContext);
  const navigate = useNavigate();
  const [refreshing, setRefreshing] = useState(false);
  const [refreshResult, setRefreshResult] = useState<{ open: boolean; success: boolean; message: string }>({
    open: false,
    success: false,
    message: '',
  });

  const onLoginClick = () => {
    navigate({ to: '/login' });
  };

  const onLogoutClick = () => {
    navigate({ to: '/logout' });
  };

  const onRefreshClick = async () => {
    if (refreshing) return;
    setRefreshing(true);
    try {
      const response = await AuthServices.RefreshToken();
      const envelope = response.data as { status: number; result?: AuthTokenResult; error?: string };
      if (envelope?.status >= 200 && envelope.status < 300 && envelope.result?.accessToken) {
        SetAccessTokenData(envelope.result);
        setAuthData({ name: envelope.result.name, email: envelope.result.resource });
        window.dispatchEvent(new Event('auth-changed'));
        const roles = envelope.result.roles?.length ? envelope.result.roles.join(', ') : 'User';
        setRefreshResult({
          open: true,
          success: true,
          message: `Session refreshed. Active roles: ${roles}.`,
        });
      } else {
        setRefreshResult({
          open: true,
          success: false,
          message: envelope?.error || 'Failed to refresh session. Please try again.',
        });
      }
    } catch (err) {
      setRefreshResult({
        open: true,
        success: false,
        message: (err as Error)?.message || 'Failed to refresh session. Please try again.',
      });
    } finally {
      setRefreshing(false);
    }
  };

  const closeDialog = () => setRefreshResult((prev) => ({ ...prev, open: false }));

  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [installed, setInstalled] = useState<boolean>(true);

  React.useEffect(() => {
    setInstalled(isStandalone());
    const onInstalled = () => setInstalled(true);
    window.addEventListener('appinstalled', onInstalled);
    return () => window.removeEventListener('appinstalled', onInstalled);
  }, []);

  return (
    <>
      {isAuthenticated ? (
        <>
          <IconButton
            aria-label="account"
            onClick={(e) => setAnchorEl(e.currentTarget)}
            sx={{
              color: 'common.white',
              bgcolor: 'primary.dark',
              '&:hover': { bgcolor: 'primary.dark', filter: 'brightness(0.9)' },
            }}
          >
            <PersonIcon />
          </IconButton>
          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={() => setAnchorEl(null)}
            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
            anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
          >
            <MenuItem onClick={() => { setAnchorEl(null); onRefreshClick(); }} disabled={refreshing}>
              <ListItemIcon><RefreshIcon fontSize="small" /></ListItemIcon>
              <ListItemText>{refreshing ? 'Refreshing...' : 'Refresh Login'}</ListItemText>
            </MenuItem>
            <Divider />
            {!installed && (
              <MenuItem onClick={() => { setAnchorEl(null); requestPwaInstall(); }}>
                <ListItemIcon><GetAppIcon fontSize="small" /></ListItemIcon>
                <ListItemText>Install App</ListItemText>
              </MenuItem>
            )}
            <MenuItem onClick={() => { setAnchorEl(null); requestPwaUpdate(); }}>
              <ListItemIcon><SystemUpdateAltIcon fontSize="small" /></ListItemIcon>
              <ListItemText>Update App</ListItemText>
            </MenuItem>
            <Divider />
            <MenuItem onClick={() => { setAnchorEl(null); onLogoutClick(); }}>
              <ListItemIcon><LogoutIcon fontSize="small" /></ListItemIcon>
              <ListItemText>Logout</ListItemText>
            </MenuItem>
          </Menu>
        </>
      ) : (
        <IconButton
          aria-label="login"
          onClick={onLoginClick}
          sx={{
            // Match the topbar hamburger / authenticated avatar: white icon on primary.dark.
            color: 'common.white',
            bgcolor: 'primary.dark',
            '&:hover': { bgcolor: 'primary.dark', filter: 'brightness(0.9)' },
          }}
        >
          <LockOpenIcon />
        </IconButton>
      )}
      <ConfirmDialog
        open={refreshResult.open}
        onCancel={closeDialog}
        onConfirm={closeDialog}
        hideCancel
        confirmLabel="OK"
        tone={refreshResult.success ? 'primary' : 'error'}
        title={refreshResult.success ? 'Login refreshed' : 'Refresh failed'}
        description={refreshResult.message}
      />
    </>
  );
};

